 db=connect(path);db.row_factory=sqlite3.Row
 sql='SELECT * FROM osm WHERE lat BETWEEN ? AND ?';args=[lat-radius_km/110,lat+radius_km/110]
 if diet:sql+=' AND '+diet+" IN ('yes','only')"
 rows=[]
 for row in db.execute(sql,args):
  r=dict(row)
